import ast
import os.path
import re
import token
from collections.abc import Callable
from typing import IO, Any

from pegen import grammar
from pegen.grammar import (
    Cut,
    Forced,
    Gather,
    GrammarVisitor,
    Group,
    Leaf,
    Lookahead,
    NamedItem,
    NameLeaf,
    NegativeLookahead,
    Opt,
    PositiveLookahead,
    Repeat0,
    Repeat1,
    Rhs,
    Rule,
    StringLeaf,
)
from pegen.parser_generator import ParserGenerator

# The generated parser follows the C generator's semantics (c_generator.py):
# an item fails only when its call returns None, only rules marked (memo) and
# left-recursive leaders are memoized, alternatives consisting of a single
# invalid_ rule run only in the second pass, and EXTRA in an action expands to
# the node location the C parser computes.  The runtime (Parser, memoize,
# memoize_left_rec) comes from the grammar's @header.

MODULE_PREFIX = """\
#!/usr/bin/env python3.8
# @generated by pegen from {filename}

from pegen.parser import memoize, memoize_left_rec, Parser

"""

EXTRA = (
    "lineno=_start_lineno, col_offset=_start_col_offset, "
    "end_lineno=_end_lineno, end_col_offset=_end_col_offset"
)

BASE_TOKENS = {
    "NAME": "p.name_token()",
    "NUMBER": "p.number_token()",
    "STRING": "p.string_token()",
    "SOFT_KEYWORD": "p.soft_keyword_token()",
}


class PythonCallMakerVisitor(GrammarVisitor):
    """Returns (variable name, call expression, kind) for an item.

    kind is "opt" for items that always succeed, "lookahead" for boolean
    items, and None for items that fail by returning None.
    """

    def __init__(self, parser_generator: "PythonParserGenerator"):
        self.gen = parser_generator
        self.cache: dict[str, str] = {}

    def visit_NameLeaf(self, node: NameLeaf) -> tuple[str | None, str, str | None]:
        name = node.value
        if name in BASE_TOKENS:
            return f"{name.lower()}_var", BASE_TOKENS[name], None
        if name in self.gen.tokens:
            return f"{name.lower()}_var", f"p.expect_token({getattr(token, name)})", None
        return f"{name}_var", f"p.{name}()", None

    def visit_StringLeaf(self, node: StringLeaf) -> tuple[str | None, str, str | None]:
        val = ast.literal_eval(node.value)
        if re.match(r"[a-zA-Z_]\w*\Z", val):  # This is a keyword
            if node.value.endswith("'"):
                return "_keyword", f"p.expect_token({self.gen.keywords[val]})", None
            return "_keyword", f"p.expect_soft_keyword({node.value})", None
        return "_literal", f"p.expect_token({token.EXACT_TOKEN_TYPES[val]})", None

    def visit_NamedItem(self, node: NamedItem) -> tuple[str | None, str, str | None]:
        name, call, kind = self.visit(node.item)
        if node.name:
            name = node.name
        return name, call, kind

    def lookahead_call_helper(self, node: Lookahead, positive: bool) -> tuple[None, str, str]:
        _, call, _ = self.visit(node.node)
        head, tail = call.split("(", 1)
        assert tail[-1] == ")"
        tail = tail[:-1]
        args = f"{head}, {tail}" if tail else head
        return None, f"p.lookahead({positive}, {args})", "lookahead"

    def visit_PositiveLookahead(self, node: PositiveLookahead) -> tuple[None, str, str]:
        return self.lookahead_call_helper(node, True)

    def visit_NegativeLookahead(self, node: NegativeLookahead) -> tuple[None, str, str]:
        return self.lookahead_call_helper(node, False)

    def visit_Opt(self, node: Opt) -> tuple[str, str, str]:
        _, call, _ = self.visit(node.node)
        return "_opt_var", call, "opt"

    def _generate_artificial_rule_call(
        self,
        node: Any,
        prefix: str,
        rule_generation_func: Callable[[], str],
    ) -> tuple[str, str, None]:
        key = f"{prefix}_{node}"
        if key not in self.cache:
            self.cache[key] = rule_generation_func()
        name = self.cache[key]
        return f"{name}_var", f"p.{name}()", None

    def visit_Rhs(self, node: Rhs) -> tuple[str | None, str, str | None]:
        if node.can_be_inlined:
            return self.visit(node.alts[0].items[0])
        return self._generate_artificial_rule_call(
            node, "rhs", lambda: self.gen.artificial_rule_from_rhs(node)
        )

    def visit_Repeat0(self, node: Repeat0) -> tuple[str, str, None]:
        return self._generate_artificial_rule_call(
            node, "repeat0", lambda: self.gen.artificial_rule_from_repeat(node.node, is_repeat1=False)
        )

    def visit_Repeat1(self, node: Repeat1) -> tuple[str, str, None]:
        return self._generate_artificial_rule_call(
            node, "repeat1", lambda: self.gen.artificial_rule_from_repeat(node.node, is_repeat1=True)
        )

    def visit_Gather(self, node: Gather) -> tuple[str, str, None]:
        return self._generate_artificial_rule_call(
            node, "gather", lambda: self.gen.artificial_rule_from_gather(node)
        )

    def visit_Group(self, node: Group) -> tuple[str | None, str, str | None]:
        return self.visit(node.rhs)

    def visit_Cut(self, node: Cut) -> tuple[str, str, str]:
        return "_cut_var", "True", "cut"

    def visit_Forced(self, node: Forced) -> tuple[str, str, None]:
        if isinstance(node.node, Leaf):
            val = ast.literal_eval(node.node.value)
            return "_literal", f"p.expect_forced_token({token.EXACT_TOKEN_TYPES[val]}, {val!r})", None
        if isinstance(node.node, Group):
            _, call, _ = self.visit(node.node.rhs)
            return "_literal", f"p.expect_forced_result({call}, {str(node.node.rhs)!r})", None
        raise NotImplementedError(f"Forced tokens don't work with {node.node} nodes")


class PythonParserGenerator(ParserGenerator, GrammarVisitor):
    def __init__(
        self,
        grammar: grammar.Grammar,
        file: IO[str] | None,
        tokens: set[str] = set(token.tok_name.values()),
        location_formatting: str | None = None,
        unreachable_formatting: str | None = None,
    ):
        tokens.add("SOFT_KEYWORD")
        super().__init__(grammar, tokens, file)
        self.callmakervisitor: PythonCallMakerVisitor = PythonCallMakerVisitor(self)
        self.location_formatting = location_formatting or EXTRA

    def generate(self, filename: str) -> None:
        self.collect_rules()
        header = self.grammar.metas.get("header", MODULE_PREFIX)
        if header is not None:
            basename = os.path.basename(filename)
            self.print(header.rstrip("\n").format(filename=basename))
        subheader = self.grammar.metas.get("subheader", "")
        if subheader:
            self.print(subheader)
        cls_name = self.grammar.metas.get("class", "GeneratedParser")
        self.print("# Keywords and soft keywords are listed at the end of the parser definition.")
        self.print(f"class {cls_name}(Parser):")
        for rule in self.all_rules.values():
            self.print()
            with self.indent():
                self.visit(rule)

        self.print()
        with self.indent():
            self.print(f"KEYWORDS = {self.keywords!r}")
            self.print(f"SOFT_KEYWORDS = {tuple(sorted(self.soft_keywords))!r}")

        trailer = self.grammar.metas.get("trailer", "")
        if trailer:
            self.print(trailer.rstrip("\n"))

    def visit_Rule(self, node: Rule) -> None:
        is_loop = node.is_loop()
        is_gather = node.is_gather()
        rhs = node.flatten()
        if node.left_recursive:
            if node.leader:
                self.print("@memoize_left_rec")
        elif node.memo:
            self.print("@memoize")
        self.print(f"def {node.name}(p):")
        with self.indent():
            for line in str(node).splitlines():
                self.print(f"# {line}")
            without_invalid = node.name.endswith("without_invalid")
            if without_invalid:
                self.print("_prev_call_invalid = p.call_invalid_rules")
                self.print("p.call_invalid_rules = False")
                self.print("try:")
                with self.indent():
                    self.visit_rule_body(node, rhs, is_loop, is_gather)
                self.print("finally:")
                with self.indent():
                    self.print("p.call_invalid_rules = _prev_call_invalid")
            else:
                self.visit_rule_body(node, rhs, is_loop, is_gather)

    def visit_rule_body(self, node: Rule, rhs: Rhs, is_loop: bool, is_gather: bool) -> None:
        self.print("_mark = p.mark")
        if any(alt.action and "EXTRA" in alt.action for alt in rhs.alts):
            self.print("if _mark == p.fill:")
            with self.indent():
                self.print("p.fill_token()")
            self.print("_start_lineno = p.tokens[_mark].lineno")
            self.print("_start_col_offset = p.tokens[_mark].col_offset")
        if is_loop:
            self.print("_children = []")
        self.visit(rhs, is_loop=is_loop, is_gather=is_gather)
        if is_loop:
            if node.name.startswith("_loop1"):
                self.print("return _children or None")
            else:
                self.print("return _children")
        else:
            self.print("return None")

    def visit_NamedItem(self, node: NamedItem) -> None:
        name, call, kind = self.callmakervisitor.visit(node.item)
        if node.name:
            name = node.name
        if name and name != "_cut_var":
            name = self.dedupe(name)
        if kind == "lookahead":
            self.print(call)
        elif kind == "opt":
            self.print(f"(({name} := {call}) or True)")
        elif kind == "cut":
            self.print(f"({name} := True)")
        else:
            self.print(f"({name} := {call}) is not None")

    def visit_Rhs(self, node: Rhs, is_loop: bool = False, is_gather: bool = False) -> None:
        if is_loop:
            assert len(node.alts) == 1
        for alt in node.alts:
            self.visit(alt, is_loop=is_loop, is_gather=is_gather)

    def visit_Alt(self, node: grammar.Alt, is_loop: bool, is_gather: bool) -> None:
        has_cut = any(isinstance(item.item, Cut) for item in node.items)
        only_invalid = len(node.items) == 1 and str(node.items[0]).startswith("invalid_")
        with self.local_variable_context():
            if has_cut:
                self.print("_cut_var = False")
            self.print("while (" if is_loop else "if (")
            with self.indent():
                if only_invalid:
                    self.print("p.call_invalid_rules and")
                first = True
                for item in node.items:
                    if first:
                        first = False
                    else:
                        self.print("and")
                    self.visit(item)

            self.print("):")
            with self.indent():
                action = node.action
                if not action:
                    if is_gather:
                        assert len(self.local_variable_names) == 2
                        action = (
                            f"[{self.local_variable_names[0]}, *{self.local_variable_names[1]}]"
                        )
                    elif len(self.local_variable_names) == 1:
                        action = self.local_variable_names[0]
                    else:
                        action = "p.dummy_name()"
                elif "EXTRA" in action:
                    self.print("_token = p.get_last_nonnwhitespace_token()")
                    self.print("_end_lineno = _token.end_lineno")
                    self.print("_end_col_offset = _token.end_col_offset")
                    action = action.replace("EXTRA", self.location_formatting)

                if is_loop:
                    self.print(f"_children.append({action})")
                    self.print("_mark = p.mark")
                else:
                    self.print(f"return {action}")

            self.print("p.mark = _mark")
            # Skip remaining alternatives if a cut was reached.
            if has_cut:
                self.print("if _cut_var:")
                with self.indent():
                    self.print("return None")
